/* @lc app=leetcode id=3755 lang=kotlin */ class Solution { fun maxBalancedSubarray(nums: IntArray): Int = HashMap<Pair<Int, Int>, Int>().also { it[0 to 0] = 0 }.let { m -> nums.indices.fold(Triple(0, 0, 0)) { (xr, df, best), i -> (xr xor nums[i]).let { nx -> (df + (if (nums[i] % 2 == 0) 1 else -1)).let { nd -> if (m.containsKey(nx to nd)) Triple(nx, nd, maxOf(best, i + 1 - m[nx to nd]!!)) else m.put(nx to nd, i + 1).let { Triple(nx, nd, best) } } } }.third } }